(function(){const a=document.createElement("link").relList;if(a&&a.supports&&a.supports("modulepreload"))return;for(const n of document.querySelectorAll('link[rel="modulepreload"]'))i(n);new MutationObserver(n=>{for(const t of n)if(t.type==="childList")for(const s of t.addedNodes)s.tagName==="LINK"&&s.rel==="modulepreload"&&i(s)}).observe(document,{childList:!0,subtree:!0});function r(n){const t={};return n.integrity&&(t.integrity=n.integrity),n.referrerPolicy&&(t.referrerPolicy=n.referrerPolicy),n.crossOrigin==="use-credentials"?t.credentials="include":n.crossOrigin==="anonymous"?t.credentials="omit":t.credentials="same-origin",t}function i(n){if(n.ep)return;n.ep=!0;const t=r(n);fetch(n.href,t)}})();const c={T:{"Finished.":"Terminado.","Line {n} of {t}":"Línea {n} de {t}","Done! Tie the thread off at nail {n}.":"¡Listo! Ata el final del hilo en el clavo {n}.","from nail {n}":"desde el clavo {n}","Portrait – fine":"Retrato – fino","Portrait – bold":"Retrato – marcado","High-contrast graphic":"Gráfico de alto contraste","300 nails, 0.2 mm thread, up to 4,500 lines: fine detail and soft tones. Takes longest to wind.":"300 clavos, hilo de 0,2 mm, hasta 4.500 líneas: detalle fino y tonos suaves. Es el que más tarda en enrollarse.","200 nails, 0.4 mm thread, up to 2,500 lines: strong shapes that read from across a room.":"200 clavos, hilo de 0,4 mm, hasta 2.500 líneas: formas fuertes que se leen desde el otro lado de una sala.","240 nails, dark thread and a length penalty: solid areas fill and edges near the rim stay crisp. For logos and silhouettes.":"240 clavos, hilo oscuro y penalización por longitud: las zonas sólidas se llenan y los bordes cerca del aro quedan nítidos. Para logotipos y siluetas.","Preset “{name}”: {tip}":"Preajuste «{name}»: {tip}","Your last result is shown again ({n} lines{src}). Load a picture to make a new one.":"Se muestra de nuevo tu último resultado ({n} líneas{src}). Carga una imagen para hacer uno nuevo.","Project loaded: the solver reproduced the saved sequence exactly ({n} lines).":"Proyecto cargado: el cálculo reprodujo exactamente la secuencia guardada ({n} líneas).","Project loaded, but this run differs from the saved sequence. It was probably saved with another version of the app.":"Proyecto cargado, pero este cálculo difiere de la secuencia guardada. Probablemente se guardó con otra versión de la aplicación.","That project file is damaged: its picture does not match its fingerprint.":"Ese archivo de proyecto está dañado: su imagen no coincide con su huella.","That project was saved by a newer version of the app.":"Ese proyecto se guardó con una versión más nueva de la aplicación.","That is not a String Art project file.":"Ese no es un archivo de proyecto de String Art.","String Art nail template · {n} nails · {d} mm board":"Plantilla de clavos de String Art · {n} clavos · tablero de {d} mm","100 mm × 100 mm: check with a ruler":"100 mm × 100 mm: compruébalo con una regla","row {r}, column {c}":"fila {r}, columna {c}","{n} pages of {paper} for a {d} mm board.":"{n} páginas {paper} para un tablero de {d} mm.","Print these pages at actual size (100 %, no scaling), check the 100 mm square with a ruler, then trim and tape the pages together, matching the crosses in the shaded overlaps.":"Imprime estas páginas a tamaño real (100 %, sin escalar), comprueba el cuadrado de 100 mm con una regla y luego recorta y une las páginas con cinta, haciendo coincidir las cruces de las franjas sombreadas que se solapan.","Sample portrait":"Retrato de ejemplo","The sample could not be loaded.":"No se pudo cargar el ejemplo.","{n}, numbered 0 to {m} clockwise; nail 0 at the top":"{n}, numerados del 0 al {m} en sentido horario; el clavo 0 arriba","{d} mm (the circle the nails stand on)":"{d} mm (el círculo sobre el que van los clavos)","{t} mm black; you need {m} m, plus {s} m for wrapping and slack":"negro de {t} mm; necesitas {m} m, más {s} m para las vueltas y la holgura",Start:"Inicio","tie the thread to nail {n}":"ata el hilo al clavo {n}","String Art — winding instructions":"String Art — instrucciones de enrollado","Made with String Art version {v} on {d}.":"Hecho con String Art versión {v} el {d}.","The finished piece, as simulated":"La pieza terminada, simulada","How to wind":"Cómo enrollar","Number the nails 0 to {m} clockwise, starting with nail 0 at the top (12 o'clock).":"Numera los clavos del 0 al {m} en sentido horario, empezando con el clavo 0 arriba (las 12 en punto).","Tie the thread to nail {n}.":"Ata el hilo al clavo {n}.","Read each block left to right: take the thread straight across the board to the next nail, once around it, and on to the next. Keep the thread taut.":"Lee cada bloque de izquierda a derecha: lleva el hilo en línea recta a través del tablero hasta el siguiente clavo, dale una vuelta y sigue al siguiente. Mantén el hilo tenso.","Tick a block when it is done. The ticks are remembered in this browser, so you can stop and carry on later.":"Marca un bloque cuando lo termines. Las marcas se recuerdan en este navegador, así que puedes parar y seguir más tarde.","After the last nail, tie the thread off.":"Después del último clavo, ata el final del hilo.","Print or save as PDF":"Imprimir o guardar como PDF","{n} of {t} blocks done":"{n} de {t} bloques terminados","Low contrast (spread {s}). String art draws with the differences between areas: with little contrast every line darkens everything about equally and the result is a grey haze. Raise the contrast, try the local contrast boost, or choose a picture with stronger lights and darks.":"Poco contraste (dispersión {s}). El arte con hilo dibuja con las diferencias entre zonas: con poco contraste cada línea oscurece todo casi por igual y el resultado es una bruma gris. Sube el contraste, prueba el refuerzo de contraste local o elige una imagen con luces y sombras más marcadas.","Busy border. Every line starts and ends at the rim, so detail or texture near the edge turns into clutter that crosses the whole picture. Zoom in on the subject or choose a plainer background.":"Borde recargado. Cada línea empieza y termina en el borde, así que el detalle o la textura cerca del borde se convierte en un desorden que cruza toda la imagen. Acércate al motivo o elige un fondo más liso.","Good contrast and a quiet border: this picture should work well.":"Buen contraste y un borde tranquilo: esta imagen debería funcionar bien.","{d}°":"{d}°","{p} % of the board":"{p} % del tablero","String Art version {v}":"String Art versión {v}","That file could not be read. Use a JPG, PNG or WebP picture.":"No se pudo leer ese archivo. Usa una imagen JPG, PNG o WebP.","The solver stopped with an error.":"El cálculo se detuvo por un error.","Preparing the lines…":"Preparando las líneas…","Line {n} of {k} · RMSE {e}":"Línea {n} de {k} · RMSE {e}","Paused.":"En pausa.","The solver stopped with an error: {e}":"El cálculo se detuvo por un error: {e}","Done: {n} lines, the most allowed.":"Listo: {n} líneas, el máximo permitido.","Done: {n} lines. More lines would not improve the picture.":"Listo: {n} líneas. Más líneas no mejorarían la imagen.","Done: {n} lines. Every allowed line from the last nail has been used.":"Listo: {n} líneas. Ya se usaron todas las líneas permitidas desde el último clavo.","Stopped after {n} lines.":"Detenido después de {n} líneas.","Pausing…":"Pausando…",Resume:"Seguir",Pause:"Pausa",Lines:"Líneas","RMSE (lower is better)":"RMSE (menor es mejor)","SSIM, pixel by pixel":"SSIM, píxel a píxel","SSIM, seen from a distance":"SSIM, visto a distancia",Thread:"Hilo","{m} m, plus {s} m for wrapping and slack":"{m} m, más {s} m para las vueltas y la holgura",Time:"Tiempo","{s} s":"{s} s","Line cache":"Caché de líneas","all lines precomputed, {mb} MB":"todas las líneas precalculadas, {mb} MB","lines computed as needed":"líneas calculadas cuando hacen falta","Board diameter":"Diámetro del tablero","Diameter of the nail circle on the real board. A bigger board shows finer detail and uses more thread.":"Diámetro del círculo de clavos en el tablero real. Un tablero más grande muestra más detalle y usa más hilo.",Nails:"Clavos","How many nails around the circle. More nails give finer detail but take longer to wind.":"Cuántos clavos hay alrededor del círculo. Más clavos dan más detalle, pero lleva más tiempo enrollar el hilo.","Thread diameter":"Grosor del hilo","Thicker thread darkens faster: each line covers more of the board.":"Un hilo más grueso oscurece más rápido: cada línea cubre más tablero.","Most lines":"Máximo de líneas","The most lines to wind. The solver stops earlier if no line improves the picture any more.":"El máximo de líneas a enrollar. El cálculo se detiene antes si ninguna línea mejora ya la imagen.","Minimum nail skip":"Salto mínimo entre clavos","No line may join nails closer than this. Short lines near the rim only add clutter.":"Ninguna línea puede unir clavos más cercanos que esto. Las líneas cortas junto al borde solo ensucian.","Uses per line":"Usos por línea","How many times the thread may join the same two nails.":"Cuántas veces el hilo puede unir los mismos dos clavos.","Start nail":"Clavo inicial","The nail where the thread is tied on. Nail 0 is at the top; numbers run clockwise.":"El clavo donde se ata el hilo. El clavo 0 está arriba; la numeración va en sentido horario.","Working resolution":"Resolución de trabajo","Size of the picture the solver compares against, in pixels. Higher is more precise but slower and uses more memory.":"Tamaño de la imagen con la que compara el cálculo, en píxeles. Más alta es más precisa, pero más lenta y usa más memoria.","Darkness factor":"Factor de oscuridad","How dark one pass of thread counts. Above 1 the solver reaches the same darkness with fewer lines; below 1 it uses more.":"Cuánto oscurece una pasada de hilo. Por encima de 1 el cálculo logra la misma oscuridad con menos líneas; por debajo de 1 usa más.","Length penalty β":"Penalización por longitud β","Above 0, long lines count for less: a line's score is divided by its length to this power. It brings out detail near the edge.":"Por encima de 0, las líneas largas cuentan menos: la puntuación de una línea se divide entre su longitud elevada a esta potencia. Resalta el detalle cerca del borde.","Stop threshold ε":"Umbral de parada ε","Stop once the best line improves the picture by less than this for 20 lines in a row. 0 stops when lines stop helping.":"Se detiene cuando la mejor línea mejora la imagen menos que esto durante 20 líneas seguidas. Con 0 se detiene cuando las líneas dejan de ayudar.","What does this do?":"¿Qué hace esto?"},H:{"about.h.math":"Las matemáticas detrás","about.m.intro":"Aquí está cada paso que da la aplicación, con las ecuaciones que usa. Solo necesitas potencias, raíces cuadradas, seno y coseno, y el signo Σ, que significa «súmalos todos».","about.m1.h":"1. De una foto a un mapa de oscuridad","about.m1.a":"Una foto guarda cada píxel como tres números entre 0 y 1, para el rojo, el verde y el azul. Pero esos números están “aplastados”: las pantallas guardan la luz siguiendo una curva, para que los tonos oscuros reciban más números. Antes de hacer cuentas con la luz, la aplicación deshace la curva y obtiene la cantidad real de luz <i>L</i> a partir del valor guardado <i>v</i>:","about.m1.e1":"<i>L</i> = ((<i>v</i> + 0.055) / 1.055)<sup>2.4</sup>      (para valores muy oscuros: <i>L</i> = <i>v</i> / 12.92)","about.m1.b":"Nuestros ojos ven el verde mucho más claro que el rojo, y el azul como el más oscuro de los tres, así que el brillo <i>Y</i> de un píxel es un promedio ponderado:","about.m1.e2":"<i>Y</i> = 0.2126 <i>R</i> + 0.7152 <i>G</i> + 0.0722 <i>B</i>","about.m1.c":"El hilo es negro, así que la aplicación necesita lo contrario del brillo: cuán oscuro debe ser cada punto. Esa es la oscuridad objetivo <i>T</i>, de 0 (blanco, sin hilo) a 1 (negro, totalmente cubierto):","about.m1.e3":"<i>T</i> = 1 − <i>Y</i>","about.m1.d":"¿Por qué deshacer la curva? Porque el hilo funciona con luz real: un punto medio cubierto por hilo negro devuelve la mitad de la luz, y solo los números de luz real se suman así.","about.m2.h":"2. Dónde van los clavos","about.m2.a":"Hay <i>N</i> clavos repartidos por igual en un círculo de radio <i>R</i> alrededor del centro (<i>c</i><sub>x</sub>, <i>c</i><sub>y</sub>). El clavo 0 está arriba y la numeración va en sentido horario. El clavo <i>i</i> está en el ángulo","about.m2.e1":"<i>θ</i><sub><i>i</i></sub> = −90° + 360° · <i>i</i> / <i>N</i>","about.m2.b":"y su posición sale del coseno y el seno. En una pantalla la <i>y</i> crece hacia abajo, y por eso la numeración va en sentido horario:","about.m2.e2":"<i>x</i><sub><i>i</i></sub> = <i>c</i><sub>x</sub> + <i>R</i> cos <i>θ</i><sub><i>i</i></sub>      <i>y</i><sub><i>i</i></sub> = <i>c</i><sub>y</sub> + <i>R</i> sen <i>θ</i><sub><i>i</i></sub>","about.m2.c":"Una línea entre dos clavos separados por <i>d</i> lugares es una cuerda del círculo. En un tablero de diámetro <i>D</i> mide:","about.m2.e3":"longitud = <i>D</i> · sen(180° · <i>d</i> / <i>N</i>)","about.m2.d":"Por ejemplo, con 240 clavos en un tablero de 600 mm, los clavos 0 y 120 están uno frente al otro: sen(90°) = 1, así que la línea mide los 600 mm completos. Los clavos 0 y 60 están a un cuarto de vuelta: 600 · sen(45°) ≈ 424 mm.","about.m3.h":"3. Dibujar una línea en una cuadrícula de píxeles","about.m3.a":"Una línea recta rara vez pasa justo por el centro de los píxeles. La aplicación usa el método de Xiaolin Wu: recorre la línea columna por columna y, donde la línea pasa entre dos píxeles, reparte la tinta entre ellos. Si la línea está a una fracción <i>f</i> del camino entre el centro del píxel de arriba y el de abajo, reciben","about.m3.e1":"<i>w</i><sub>arriba</sub> = 1 − <i>f</i>      <i>w</i><sub>abajo</sub> = <i>f</i>","about.m3.b":"así que cada columna recibe siempre exactamente un píxel de tinta. Pero una línea inclinada es más larga que el número de columnas que cruza: una línea a 45° que cruza 100 columnas mide 141 píxeles. Por eso cada línea recibe una corrección","about.m3.e2":"<i>k</i> = longitud / columnas cruzadas      (entre 1 y √2 ≈ 1.41)","about.m4.h":"4. Cómo oscurece el hilo el tablero","about.m4.a":"Una pasada de hilo cubre solo una parte de un píxel. Al tamaño de trabajo, un píxel mide 600 mm / 700 ≈ 0.86 mm de ancho y el hilo 0.25 mm de grosor, así que una pasada cubre más o menos esta fracción (el factor de oscuridad, un ajuste, permite que el hilo cuente como más oscuro o más claro):","about.m4.e1":"<i>α</i> = (ancho del hilo / ancho del píxel) × factor de oscuridad = 0.25 / 0.86 × 1 ≈ 0.29","about.m4.b":"En un píxel de una línea con parte de tinta <i>w</i>, una pasada cubre <i>a</i> = <i>α</i> · <i>k</i> · <i>w</i> (nunca más de 1). Ahora la idea clave: un hilo nuevo que queda encima de los anteriores tapa la misma fracción del blanco que <b>todavía se ve</b>. Si <i>C</i> es lo oscuro que ya está un píxel, el blanco que se ve es 1 − <i>C</i>, y después de una pasada más","about.m4.e2":"1 − <i>C</i><sub>nuevo</sub> = (1 − <i>C</i>) · (1 − <i>a</i>)","about.m4.c":"Por tanto, después de <i>n</i> pasadas sobre un píxel blanco la oscuridad es","about.m4.e3":"<i>C</i> = 1 − (1 − <i>a</i>)<sup><i>n</i></sup>","about.m4.d":"Con <i>a</i> = 0.29: una pasada da 0.29, dos dan 0.50 (no 0.58), tres dan 0.64, diez dan 0.97. Los cruces se oscurecen cada vez más, pero nunca más que el negro, igual que el hilo real.","about.m5.h":"5. Elegir la siguiente línea","about.m5.a":"La aplicación mide cuánto se aleja su tablero simulado <i>C</i> del objetivo <i>T</i> con el error cuadrático: para cada píxel toma la diferencia, la eleva al cuadrado (así lo demasiado oscuro y lo demasiado claro cuentan los dos como positivo), la multiplica por la importancia de ese píxel (<i>W</i>, del pincel: 1 normalmente, hasta 3 en las zonas importantes) y lo suma todo:","about.m5.e1":"<i>E</i> = Σ <i>W</i> · (<i>T</i> − <i>C</i>)<sup>2</sup>","about.m5.b":"Enrollar una línea más oscurece cada uno de sus píxeles en <i>δ</i> = <i>a</i> · (1 − <i>C</i>). ¿Cuánto baja eso el error? Desarrollando (<i>T</i> − <i>C</i>)<sup>2</sup> − (<i>T</i> − <i>C</i> − <i>δ</i>)<sup>2</sup> se obtiene la mejora que aporta la línea:","about.m5.e2":"Δ<i>E</i> = Σ<sub>píxeles de la línea</sub> <i>W</i> · <i>δ</i> · (2(<i>T</i> − <i>C</i>) − <i>δ</i>)","about.m5.c":"Un píxel ayuda mientras todavía está más claro de lo que debería por más de la mitad de <i>δ</i>; cuando ya está bastante oscuro, más hilo ahí cuenta en contra de la línea. Desde el clavo donde está el hilo, la aplicación calcula Δ<i>E</i> para cada línea que puede enrollar a continuación (unas 200), enrolla la que tiene el Δ<i>E</i> más grande y repite desde el otro extremo de esa línea.","about.m5.d":"Esto se llama un método <b>voraz</b>: siempre toma el mejor paso siguiente y nunca mira más adelante. ¿Por qué no buscar la mejor secuencia de todas? Con 200 opciones en cada uno de 3.000 pasos hay 200<sup>3000</sup> secuencias posibles, un número de unas 6.900 cifras. Ninguna computadora podría probarlas todas; el método voraz solo necesita 200 × 3.000 = 600.000 puntuaciones, lo que tarda unos segundos.","about.m6.h":"6. Cuándo parar, y favorecer las líneas cortas","about.m6.a":"La aplicación se detiene después del máximo de líneas que permitas, o cuando el mejor Δ<i>E</i> ha estado por debajo de un umbral pequeño <i>ε</i> (normalmente 0) durante 20 líneas seguidas: entonces ninguna línea ayuda ya, y esas últimas 20 líneas se quitan. La penalización por longitud <i>β</i> divide la puntuación de cada línea entre su longitud <i>ℓ</i> elevada a una potencia:","about.m6.e1":"puntuación = Δ<i>E</i> / <i>ℓ</i><sup><i>β</i></sup>","about.m6.b":"Con <i>β</i> = 0 no cambia nada; con <i>β</i> = 1 una línea el doble de larga necesita el doble de mejora para ganar, lo que da más oportunidades a las líneas cortas cerca del borde.","about.m7.h":"7. Medir el resultado","about.m7.a":"La raíz del error cuadrático medio promedia las diferencias al cuadrado sobre los <i>n</i> píxeles del círculo y saca la raíz cuadrada, así que queda en las mismas unidades que la oscuridad (0 es perfecto):","about.m7.e1":"RMSE = √( Σ (<i>T</i> − <i>C</i>)<sup>2</sup> / <i>n</i> )","about.m7.b":"El SSIM (similitud estructural) compara pequeños parches de 7 × 7 de las dos imágenes: su oscuridad media <i>μ</i>, cuánto varían (<i>σ</i>) y cuánto varían juntos (<i>σ</i><sub>TC</sub>). Vale 1 cuando los parches coinciden y casi 0 cuando no tienen nada en común:","about.m7.e2":`SSIM = (2<i>μ</i><sub>T</sub><i>μ</i><sub>C</sub> + <i>c</i><sub>1</sub>)(2<i>σ</i><sub>TC</sub> + <i>c</i><sub>2</sub>) / ((<i>μ</i><sub>T</sub><sup>2</sup> + <i>μ</i><sub>C</sub><sup>2</sup> + <i>c</i><sub>1</sub>)(<i>σ</i><sub>T</sub><sup>2</sup> + <i>σ</i><sub>C</sub><sup>2</sup> + <i>c</i><sub>2</sub>))
<i>c</i><sub>1</sub> = 0.0001, <i>c</i><sub>2</sub> = 0.0009`,"about.m7.c":"Los números pequeños <i>c</i><sub>1</sub> y <i>c</i><sub>2</sub> evitan dividir entre cero en parches lisos. De cerca, el hilo es un enredo de líneas finas, así que la aplicación también da el SSIM después de desenfocar un poco las dos imágenes, más cercano a lo que ves a unos pasos. Por último, el hilo que necesitas es la suma de todas las longitudes de las líneas del paso 2, más un 10 % para las vueltas a los clavos y la holgura.","about.m8.h":"8. Ajustar la imagen","about.m8.a":"El contraste y el brillo actúan sobre el valor guardado <i>v</i>: el contraste <i>s</i> lo estira alejándolo del gris medio, el brillo <i>b</i> lo desplaza y la gamma <i>γ</i> lo curva, oscureciendo los tonos medios cuando <i>γ</i> es mayor que 1:","about.m8.e1":"<i>v</i>′ = ((<i>v</i> − 0.5) · <i>s</i> + 0.5 + <i>b</i>)<sup><i>γ</i></sup>","about.m8.b":"El refuerzo de contraste local (CLAHE) corta la imagen en una cuadrícula de 8 × 8 cuadrados. En cada cuadrado cuenta cuántos píxeles tienen cada tono (un histograma) y le da a cada tono un nuevo valor: la fracción de los píxeles del cuadrado que son más oscuros que él. Los tonos que comparten muchos píxeles se separan, así que aparece detalle en las zonas planas. Antes, cada cuenta se limita a un tope para no exagerar el ruido, y los cuadrados vecinos se mezclan para que no se noten las uniones.","tm.help":"Espacio, Intro o → para el siguiente clavo; ← para volver; Esc para cerrar. Tu posición se guarda en cada paso, así que puedes cerrar esto y seguir más tarde.","tm.nextBtn":"Siguiente ▶","tm.go":"Ir","tm.goto":"Ir a la línea","tm.back":"◀ Atrás","tm.board":"El tablero, con las líneas enrolladas hasta ahora y la siguiente línea resaltada","tm.after":"Después","tm.before":"Antes","tm.next":"Siguiente clavo","tm.close":"Cerrar","tm.full":"Pantalla completa","tm.speak":"Decir el clavo en voz alta","tm.title":"Modo de enhebrado","h.presets":"Preajustes","dl.thread":"Modo de enhebrado","in.project":"Abrir un proyecto","in.projNote":"Un proyecto guarda la imagen tal como la vio el cálculo, no la foto original. Para cambiar el recorte, los ajustes o las marcas del pincel, vuelve a subir la foto.","h.template":"Plantilla de clavos","tpl.hint":"Las posiciones de los clavos a tamaño real, numeradas, para pegar sobre el tablero. Imprime a tamaño real (100 %, no “ajustar a la página”) y comprueba el cuadrado de 100 mm con una regla.","tpl.paper":"Papel","tpl.pages":"Páginas para imprimir","tpl.svg":"Una sola hoja (SVG)","dl.png":"Vista previa (PNG)","dl.project":"Archivo del proyecto","dl.instructions":"Descargar las instrucciones de enrollado","dl.csv":"Secuencia (CSV)","brush.hint":"Pinta sobre la vista Objetivo. Las zonas cálidas cuentan hasta tres veces más y atraen más líneas; las frías cuentan apenas una quinta parte. Úsalo para los ojos, una boca o un borde que importe.","brush.clear":"Borrar las marcas del pincel","brush.size":"Tamaño del pincel","brush.down":"Menos importante","brush.up":"Más importante","brush.off":"Apagado","h.brush":"Pincel de importancia","h.seen":"Como la ve el cálculo","adj.reset":"Restablecer los ajustes","adj.clip":"Límite de recorte (más alto refuerza más)","adj.clahe":"Refuerzo de contraste local (CLAHE)","adj.gamma":"Gamma (por encima de 1 oscurece los medios tonos)","adj.contrast":"Contraste","adj.brightness":"Brillo","h.adjust":"Ajustar","crop.reset":"Restablecer el recorte","crop.rotate":"Girar","crop.zoom":"Acercar","crop.hint":"Arrastra para mover la imagen; usa la rueda o pellizca para acercar.","crop.label":"La imagen bajo el círculo del tablero: arrastra para moverla, usa la rueda o pellizca para acercar",title:"String Art — Un hilo, una imagen",meta:"Convierte una imagen en arte con hilo: un solo hilo continuo enrollado entre clavos en un marco circular. La aplicación encuentra el orden de clavos que mejor reproduce la imagen y muestra una vista previa realista, todo en tu navegador.",sub:"un hilo, una imagen","nav.about":"Acerca de","nav.projects":"← Todos los proyectos","h.picture":"Imagen","in.upload":"Subir una imagen","in.sample":"Usar el ejemplo","in.thumb":"La imagen como la ve el cálculo","in.hint":"Elige una imagen: un rostro u objeto con fuerte contraste sobre un fondo liso funciona mejor. No se sube nada a ningún sitio; todo se ejecuta en tu navegador.","h.params":"Parámetros","run.run":"Calcular","run.pause":"Pausa","run.cancel":"Cancelar","view.label":"Mostrar","view.thread":"Hilo","view.target":"Objetivo","view.both":"Lado a lado","view.threadLabel":"Vista previa del hilo sobre el tablero","view.threadCap":"hilo, dibujado con su grosor real","view.targetLabel":"El objetivo al que apunta el cálculo","view.targetCap":"oscuridad objetivo","h.metrics":"Resultado","log.summary":"Registro del cálculo","about.title":"Acerca de String Art","about.back":"← Volver a la aplicación","about.h1":"Acerca de String Art","about.p1":"String Art convierte una imagen en instrucciones para una artesanía clásica: clavos alrededor de un tablero circular y un solo hilo negro enrollado de clavo en clavo, miles de veces, hasta que los cruces del hilo dibujan la imagen. La aplicación calcula el orden de los clavos y muestra cómo se verá la pieza terminada.","about.h.how":"Cómo elige las líneas","about.how":"La imagen se convierte en un mapa de cuán oscuro debe ser cada punto. Partiendo de un clavo, la aplicación prueba cada línea que puede enrollar a continuación y se queda con la que acerca más el tablero simulado a ese mapa; luego sigue desde donde termina esa línea. El hilo oscurece el tablero como lo hace un hilo real: cada pasada tapa una fracción del blanco que aún se ve, así que los cruces se oscurecen, pero nunca más que el negro. Se detiene al llegar al máximo de líneas que permitas o cuando ninguna línea mejora ya la imagen.","about.h.numbers":"Los números","about.numbers":"El RMSE mide cuánto se aleja el tablero simulado del objetivo, píxel a píxel (0 es una coincidencia perfecta). El SSIM compara brillo, contraste y estructura locales (1 es idéntico); como el hilo es una textura fina de líneas, la aplicación también da el SSIM tras un ligero desenfoque, más cercano a lo que ves a unos pasos. La longitud del hilo es la suma de todas las líneas, con un 10 % más para las vueltas a los clavos y la holgura.","about.h.private":"Tus imágenes se quedan contigo","about.private":"Todo se ejecuta en tu navegador. Las imágenes nunca se suben.","about.h.status":"Qué hace","about.status":"Versión 1.0. Prepara la imagen —recórtala, acércala y gírala, ajusta brillo, contraste y gamma, refuerza el contraste local y pinta lo que importa— con una comprobación que avisa de las imágenes que no funcionarán bien; elige un preajuste o ajusta cada parámetro; y mira cómo se enrolla el hilo. Luego imprime la plantilla de clavos a tamaño real y las instrucciones de enrollado, y enrolla la pieza con el modo de enhebrado, que muestra (y puede decir) el siguiente clavo y recuerda dónde vas. Tus ajustes y tu último resultado se recuerdan en este navegador."}},p={T:{"Finished.":"Færdig.","Line {n} of {t}":"Linje {n} af {t}","Done! Tie the thread off at nail {n}.":"Færdig! Bind tråden af ved søm {n}.","from nail {n}":"fra søm {n}","Portrait – fine":"Portræt – fint","Portrait – bold":"Portræt – kraftigt","High-contrast graphic":"Grafik med høj kontrast","300 nails, 0.2 mm thread, up to 4,500 lines: fine detail and soft tones. Takes longest to wind.":"300 søm, 0,2 mm tråd, op til 4.500 linjer: fine detaljer og bløde toner. Tager længst tid at vikle.","200 nails, 0.4 mm thread, up to 2,500 lines: strong shapes that read from across a room.":"200 søm, 0,4 mm tråd, op til 2.500 linjer: kraftige former, der kan ses på tværs af et rum.","240 nails, dark thread and a length penalty: solid areas fill and edges near the rim stay crisp. For logos and silhouettes.":"240 søm, mørk tråd og længdestraf: ensfarvede områder fyldes ud, og kanter nær randen forbliver skarpe. Til logoer og silhuetter.","Preset “{name}”: {tip}":"Forvalg “{name}”: {tip}","Your last result is shown again ({n} lines{src}). Load a picture to make a new one.":"Dit seneste resultat vises igen ({n} linjer{src}). Indlæs et billede for at lave et nyt.","Project loaded: the solver reproduced the saved sequence exactly ({n} lines).":"Projekt indlæst: beregningen gentog den gemte rækkefølge præcist ({n} linjer).","Project loaded, but this run differs from the saved sequence. It was probably saved with another version of the app.":"Projekt indlæst, men denne beregning afviger fra den gemte rækkefølge. Det er nok gemt med en anden version af appen.","That project file is damaged: its picture does not match its fingerprint.":"Projektfilen er beskadiget: billedet passer ikke til dets fingeraftryk.","That project was saved by a newer version of the app.":"Projektet er gemt med en nyere version af appen.","That is not a String Art project file.":"Det er ikke en String Art-projektfil.","String Art nail template · {n} nails · {d} mm board":"String Art-sømskabelon · {n} søm · plade på {d} mm","100 mm × 100 mm: check with a ruler":"100 mm × 100 mm: kontrollér med en lineal","row {r}, column {c}":"række {r}, kolonne {c}","{n} pages of {paper} for a {d} mm board.":"{n} sider i {paper} til en plade på {d} mm.","Print these pages at actual size (100 %, no scaling), check the 100 mm square with a ruler, then trim and tape the pages together, matching the crosses in the shaded overlaps.":"Udskriv siderne i faktisk størrelse (100 %, ingen skalering), kontrollér kvadratet på 100 mm med en lineal, og klip og tape så siderne sammen, så krydsene i de skraverede overlap passer.","Sample portrait":"Eksempelportræt","The sample could not be loaded.":"Eksemplet kunne ikke indlæses.","{n}, numbered 0 to {m} clockwise; nail 0 at the top":"{n}, nummereret 0 til {m} med uret; søm 0 øverst","{d} mm (the circle the nails stand on)":"{d} mm (cirklen, sømmene står på)","{t} mm black; you need {m} m, plus {s} m for wrapping and slack":"{t} mm sort; du skal bruge {m} m plus {s} m til omvikling og slæk",Start:"Start","tie the thread to nail {n}":"bind tråden til søm {n}","String Art — winding instructions":"String Art — viklevejledning","Made with String Art version {v} on {d}.":"Lavet med String Art version {v} den {d}.","The finished piece, as simulated":"Det færdige værk, simuleret","How to wind":"Sådan vikler du","Number the nails 0 to {m} clockwise, starting with nail 0 at the top (12 o'clock).":"Nummerér sømmene 0 til {m} med uret, med søm 0 øverst (klokken 12).","Tie the thread to nail {n}.":"Bind tråden til søm {n}.","Read each block left to right: take the thread straight across the board to the next nail, once around it, and on to the next. Keep the thread taut.":"Læs hver blok fra venstre mod højre: før tråden lige over pladen til det næste søm, én gang rundt om det og videre til det næste. Hold tråden stram.","Tick a block when it is done. The ticks are remembered in this browser, so you can stop and carry on later.":"Sæt flueben ved en blok, når den er færdig. Fluebenene huskes i denne browser, så du kan holde pause og fortsætte senere.","After the last nail, tie the thread off.":"Bind tråden af efter det sidste søm.","Print or save as PDF":"Udskriv eller gem som PDF","{n} of {t} blocks done":"{n} af {t} blokke færdige","Low contrast (spread {s}). String art draws with the differences between areas: with little contrast every line darkens everything about equally and the result is a grey haze. Raise the contrast, try the local contrast boost, or choose a picture with stronger lights and darks.":"Lav kontrast (spredning {s}). Trådkunst tegner med forskellene mellem områder: med lidt kontrast gør hver linje alt næsten lige mørkt, og resultatet bliver en grå dis. Skru op for kontrasten, prøv den lokale kontrastforstærkning, eller vælg et billede med kraftigere lys og skygge.","Busy border. Every line starts and ends at the rim, so detail or texture near the edge turns into clutter that crosses the whole picture. Zoom in on the subject or choose a plainer background.":"Uroligt kantområde. Hver linje starter og slutter ved kanten, så detaljer eller tekstur nær kanten bliver til rod, der krydser hele billedet. Zoom ind på motivet, eller vælg en mere ensfarvet baggrund.","Good contrast and a quiet border: this picture should work well.":"God kontrast og en rolig kant: dette billede burde fungere godt.","{d}°":"{d}°","{p} % of the board":"{p} % af pladen","String Art version {v}":"String Art version {v}","That file could not be read. Use a JPG, PNG or WebP picture.":"Filen kunne ikke læses. Brug et JPG-, PNG- eller WebP-billede.","The solver stopped with an error.":"Beregningen stoppede med en fejl.","Preparing the lines…":"Forbereder linjerne …","Line {n} of {k} · RMSE {e}":"Linje {n} af {k} · RMSE {e}","Paused.":"Sat på pause.","The solver stopped with an error: {e}":"Beregningen stoppede med en fejl: {e}","Done: {n} lines, the most allowed.":"Færdig: {n} linjer, det højest tilladte.","Done: {n} lines. More lines would not improve the picture.":"Færdig: {n} linjer. Flere linjer ville ikke gøre billedet bedre.","Done: {n} lines. Every allowed line from the last nail has been used.":"Færdig: {n} linjer. Alle tilladte linjer fra det sidste søm er brugt.","Stopped after {n} lines.":"Stoppet efter {n} linjer.","Pausing…":"Sætter på pause …",Resume:"Fortsæt",Pause:"Pause",Lines:"Linjer","RMSE (lower is better)":"RMSE (lavere er bedre)","SSIM, pixel by pixel":"SSIM, pixel for pixel","SSIM, seen from a distance":"SSIM, set på afstand",Thread:"Tråd","{m} m, plus {s} m for wrapping and slack":"{m} m plus {s} m til omvikling og slæk",Time:"Tid","{s} s":"{s} s","Line cache":"Linjecache","all lines precomputed, {mb} MB":"alle linjer beregnet på forhånd, {mb} MB","lines computed as needed":"linjer beregnes efter behov","Board diameter":"Pladens diameter","Diameter of the nail circle on the real board. A bigger board shows finer detail and uses more thread.":"Diameteren af sømcirklen på den rigtige plade. En større plade viser finere detaljer og bruger mere tråd.",Nails:"Søm","How many nails around the circle. More nails give finer detail but take longer to wind.":"Hvor mange søm der sidder rundt om cirklen. Flere søm giver finere detaljer, men tager længere tid at vikle.","Thread diameter":"Trådens tykkelse","Thicker thread darkens faster: each line covers more of the board.":"Tykkere tråd gør hurtigere mørkt: hver linje dækker mere af pladen.","Most lines":"Højst antal linjer","The most lines to wind. The solver stops earlier if no line improves the picture any more.":"Det højeste antal linjer, der vikles. Beregningen stopper før, hvis ingen linje gør billedet bedre længere.","Minimum nail skip":"Mindste sømspring","No line may join nails closer than this. Short lines near the rim only add clutter.":"Ingen linje må forbinde søm, der sidder tættere end dette. Korte linjer ved kanten giver kun rod.","Uses per line":"Brug pr. linje","How many times the thread may join the same two nails.":"Hvor mange gange tråden må forbinde de samme to søm.","Start nail":"Startsøm","The nail where the thread is tied on. Nail 0 is at the top; numbers run clockwise.":"Sømmet, hvor tråden bindes fast. Søm 0 sidder øverst; numrene løber med uret.","Working resolution":"Arbejdsopløsning","Size of the picture the solver compares against, in pixels. Higher is more precise but slower and uses more memory.":"Størrelsen på billedet, beregningen sammenligner med, i pixel. Højere er mere præcist, men langsommere og bruger mere hukommelse.","Darkness factor":"Mørkefaktor","How dark one pass of thread counts. Above 1 the solver reaches the same darkness with fewer lines; below 1 it uses more.":"Hvor mørk én gang tråd regnes for. Over 1 når beregningen samme mørke med færre linjer; under 1 bruger den flere.","Length penalty β":"Længdestraf β","Above 0, long lines count for less: a line's score is divided by its length to this power. It brings out detail near the edge.":"Over 0 tæller lange linjer mindre: en linjes point divideres med dens længde opløftet til denne potens. Det fremhæver detaljer nær kanten.","Stop threshold ε":"Stopgrænse ε","Stop once the best line improves the picture by less than this for 20 lines in a row. 0 stops when lines stop helping.":"Stop, når den bedste linje forbedrer billedet med mindre end dette 20 linjer i træk. Med 0 stopper den, når linjerne holder op med at hjælpe.","What does this do?":"Hvad gør denne?"},H:{"about.h.math":"Matematikken bag","about.m.intro":"Her er hvert skridt, appen tager, med de ligninger, den bruger. Du skal kun kende potenser, kvadratrødder, sinus og cosinus og tegnet Σ, som betyder “læg dem alle sammen”.","about.m1.h":"1. Fra et foto til et kort over mørke","about.m1.a":"Et foto gemmer hver pixel som tre tal mellem 0 og 1 for rød, grøn og blå. Men tallene er “klemt sammen”: skærme gemmer lys efter en kurve, så de mørke nuancer får flere af tallene. Før appen regner med lys, retter den kurven ud igen og finder den virkelige mængde lys <i>L</i> ud fra den gemte værdi <i>v</i>:","about.m1.e1":"<i>L</i> = ((<i>v</i> + 0,055) / 1,055)<sup>2,4</sup>      (for meget mørke værdier: <i>L</i> = <i>v</i> / 12,92)","about.m1.b":"Vores øjne ser grøn som meget lysere end rød og blå som den mørkeste af de tre, så en pixels lysstyrke <i>Y</i> er et vægtet gennemsnit:","about.m1.e2":"<i>Y</i> = 0,2126 <i>R</i> + 0,7152 <i>G</i> + 0,0722 <i>B</i>","about.m1.c":"Tråden er sort, så appen har brug for det modsatte af lysstyrke: hvor mørkt hvert punkt skal være. Det er det ønskede mørke <i>T</i>, fra 0 (hvidt, ingen tråd) til 1 (sort, helt dækket):","about.m1.e3":"<i>T</i> = 1 − <i>Y</i>","about.m1.d":"Hvorfor rette kurven ud? Fordi tråd virker med virkeligt lys: et punkt, der er halvt dækket af sort tråd, sender halvdelen af lyset tilbage, og kun tal for virkeligt lys lægges sådan sammen.","about.m2.h":"2. Hvor sømmene sidder","about.m2.a":"Der er <i>N</i> søm med lige stor afstand på en cirkel med radius <i>R</i> omkring centrum (<i>c</i><sub>x</sub>, <i>c</i><sub>y</sub>). Søm 0 sidder øverst, og numrene går med uret. Søm <i>i</i> sidder ved vinklen","about.m2.e1":"<i>θ</i><sub><i>i</i></sub> = −90° + 360° · <i>i</i> / <i>N</i>","about.m2.b":"og placeringen findes med cosinus og sinus. På en skærm vokser <i>y</i> nedad, og det er derfor, numrene går med uret:","about.m2.e2":"<i>x</i><sub><i>i</i></sub> = <i>c</i><sub>x</sub> + <i>R</i> cos <i>θ</i><sub><i>i</i></sub>      <i>y</i><sub><i>i</i></sub> = <i>c</i><sub>y</sub> + <i>R</i> sin <i>θ</i><sub><i>i</i></sub>","about.m2.c":"En linje mellem to søm, der er <i>d</i> pladser fra hinanden, er en korde i cirklen. På en plade med diameteren <i>D</i> er den så lang:","about.m2.e3":"længde = <i>D</i> · sin(180° · <i>d</i> / <i>N</i>)","about.m2.d":"For eksempel: med 240 søm på en plade på 600 mm sidder søm 0 og 120 lige over for hinanden: sin(90°) = 1, så linjen er hele 600 mm. Søm 0 og 60 er en kvart omgang fra hinanden: 600 · sin(45°) ≈ 424 mm.","about.m3.h":"3. At tegne en linje på et gitter af pixel","about.m3.a":"En ret linje går sjældent præcis gennem midten af pixel. Appen bruger Xiaolin Wus metode: den går langs linjen én kolonne ad gangen, og hvor linjen går mellem to pixel, deler den blækket mellem dem. Hvis linjen ligger en brøkdel <i>f</i> af vejen fra midten af den øverste pixel til den nederste, får de","about.m3.e1":"<i>w</i><sub>øverst</sub> = 1 − <i>f</i>      <i>w</i><sub>nederst</sub> = <i>f</i>","about.m3.b":"så hver kolonne altid får præcis én pixel blæk. Men en skrå linje er længere end antallet af kolonner, den krydser: en linje på 45° over 100 kolonner er 141 pixel lang. Derfor får hver linje en rettelse","about.m3.e2":"<i>k</i> = længde / krydsede kolonner      (mellem 1 og √2 ≈ 1,41)","about.m4.h":"4. Hvordan tråden gør pladen mørk","about.m4.a":"Én gang tråd dækker kun en del af en pixel. I arbejdsstørrelsen er en pixel 600 mm / 700 ≈ 0,86 mm bred, og tråden er 0,25 mm tyk, så én gang tråd dækker omtrent denne brøkdel (mørkefaktoren, en indstilling, lader tråden tælle som mørkere eller lysere):","about.m4.e1":"<i>α</i> = (trådens bredde / pixlens bredde) × mørkefaktor = 0,25 / 0,86 × 1 ≈ 0,29","about.m4.b":"På en pixel i en linje med blækandelen <i>w</i> dækker én gang tråd <i>a</i> = <i>α</i> · <i>k</i> · <i>w</i> (aldrig mere end 1). Nu den vigtige idé: en ny tråd, der ligger oven på de gamle, dækker den samme brøkdel af det hvide, der <b>stadig ses</b>. Hvis <i>C</i> er, hvor mørk en pixel allerede er, er det hvide, der ses, 1 − <i>C</i>, og efter én gang mere","about.m4.e2":"1 − <i>C</i><sub>ny</sub> = (1 − <i>C</i>) · (1 − <i>a</i>)","about.m4.c":"Efter <i>n</i> gange over en hvid pixel er mørket derfor","about.m4.e3":"<i>C</i> = 1 − (1 − <i>a</i>)<sup><i>n</i></sup>","about.m4.d":"Med <i>a</i> = 0,29: én gang giver 0,29, to giver 0,50 (ikke 0,58), tre giver 0,64, ti giver 0,97. Krydsninger bliver mørkere og mørkere, men aldrig mørkere end sort — ligesom rigtig tråd.","about.m5.h":"5. At vælge den næste linje","about.m5.a":"Appen måler, hvor langt den simulerede plade <i>C</i> er fra målet <i>T</i>, med den kvadrerede fejl: for hver pixel tager den forskellen, sætter den i anden (så både for mørkt og for lyst tæller som positivt), ganger med, hvor vigtig pixlen er (<i>W</i>, fra penslen: normalt 1, op til 3 i vigtige områder), og lægger det hele sammen:","about.m5.e1":"<i>E</i> = Σ <i>W</i> · (<i>T</i> − <i>C</i>)<sup>2</sup>","about.m5.b":"At vikle én linje mere gør hver af dens pixel mørkere med <i>δ</i> = <i>a</i> · (1 − <i>C</i>). Hvor meget sænker det fejlen? Når man regner (<i>T</i> − <i>C</i>)<sup>2</sup> − (<i>T</i> − <i>C</i> − <i>δ</i>)<sup>2</sup> ud, får man den forbedring, linjen giver:","about.m5.e2":"Δ<i>E</i> = Σ<sub>linjens pixel</sub> <i>W</i> · <i>δ</i> · (2(<i>T</i> − <i>C</i>) − <i>δ</i>)","about.m5.c":"En pixel hjælper, så længe den stadig er lysere, end den skal være, med mere end halvdelen af <i>δ</i>; når den er mørk nok, tæller mere tråd dér imod linjen. Fra det søm, tråden er ved, regner appen Δ<i>E</i> ud for hver linje, den må vikle som den næste (omkring 200), vikler den med størst Δ<i>E</i> og gentager fra den anden ende af linjen.","about.m5.d":"Det kaldes en <b>grådig</b> metode: den tager altid det bedste næste skridt og kigger aldrig længere frem. Hvorfor ikke finde den allerbedste rækkefølge? Med 200 valg ved hvert af 3.000 skridt er der 200<sup>3000</sup> mulige rækkefølger — et tal med omkring 6.900 cifre. Ingen computer kunne prøve dem alle; den grådige metode skal kun bruge 200 × 3.000 = 600.000 udregninger, og det tager få sekunder.","about.m6.h":"6. Hvornår der skal stoppes, og at foretrække korte linjer","about.m6.a":"Appen stopper efter det højeste antal linjer, du tillader, eller når det bedste Δ<i>E</i> har ligget under en lille grænse <i>ε</i> (normalt 0) i 20 linjer i træk: så hjælper ingen linje længere, og de sidste 20 linjer tages ud igen. Længdestraffen <i>β</i> dividerer hver linjes point med dens længde <i>ℓ</i> opløftet til en potens:","about.m6.e1":"point = Δ<i>E</i> / <i>ℓ</i><sup><i>β</i></sup>","about.m6.b":"Med <i>β</i> = 0 ændres intet; med <i>β</i> = 1 skal en dobbelt så lang linje give dobbelt så stor forbedring for at vinde, så korte linjer nær kanten får en bedre chance.","about.m7.h":"7. At måle resultatet","about.m7.a":"Kvadratroden af den gennemsnitlige kvadrerede fejl tager gennemsnittet af de kvadrerede forskelle over alle <i>n</i> pixel i cirklen og trækker kvadratroden, så den er i samme enheder som mørket (0 er perfekt):","about.m7.e1":"RMSE = √( Σ (<i>T</i> − <i>C</i>)<sup>2</sup> / <i>n</i> )","about.m7.b":"SSIM (strukturel lighed) sammenligner små udsnit på 7 × 7 af de to billeder: deres gennemsnitlige mørke <i>μ</i>, hvor meget de varierer (<i>σ</i>), og hvor meget de varierer sammen (<i>σ</i><sub>TC</sub>). Den er 1, når udsnittene passer, og tæt på 0, når de intet har til fælles:","about.m7.e2":`SSIM = (2<i>μ</i><sub>T</sub><i>μ</i><sub>C</sub> + <i>c</i><sub>1</sub>)(2<i>σ</i><sub>TC</sub> + <i>c</i><sub>2</sub>) / ((<i>μ</i><sub>T</sub><sup>2</sup> + <i>μ</i><sub>C</sub><sup>2</sup> + <i>c</i><sub>1</sub>)(<i>σ</i><sub>T</sub><sup>2</sup> + <i>σ</i><sub>C</sub><sup>2</sup> + <i>c</i><sub>2</sub>))
<i>c</i><sub>1</sub> = 0,0001, <i>c</i><sub>2</sub> = 0,0009`,"about.m7.c":"De små tal <i>c</i><sub>1</sub> og <i>c</i><sub>2</sub> forhindrer, at der divideres med nul i ensfarvede udsnit. Tæt på er tråd et virvar af tynde linjer, så appen giver også SSIM, efter at begge billeder er gjort lidt slørede — det ligner mere det, du ser fra et par skridts afstand. Til sidst er den tråd, du skal bruge, summen af alle linjelængderne fra trin 2 plus 10 % til omviklingen om sømmene og slæk.","about.m8.h":"8. At justere billedet","about.m8.a":"Kontrast og lysstyrke virker på den gemte værdi <i>v</i>: kontrasten <i>s</i> strækker den væk fra mellemgrå, lysstyrken <i>b</i> flytter den, og gammaen <i>γ</i> bøjer den, så mellemtonerne bliver mørkere, når <i>γ</i> er over 1:","about.m8.e1":"<i>v</i>′ = ((<i>v</i> − 0,5) · <i>s</i> + 0,5 + <i>b</i>)<sup><i>γ</i></sup>","about.m8.b":"Den lokale kontrastforstærkning (CLAHE) deler billedet op i et gitter på 8 × 8 felter. I hvert felt tæller den, hvor mange pixel der har hver nuance (et histogram), og giver hver nuance en ny værdi: den andel af feltets pixel, der er mørkere end den. Nuancer, som mange pixel deler, bliver spredt ud, så der kommer detaljer frem i flade områder. Først begrænses hver optælling til en grænse, så støj ikke pustes op, og nabofelter blandes, så der ikke ses sømme.","tm.help":"Mellemrum, Enter eller → for det næste søm; ← for at gå tilbage; Esc for at lukke. Din plads gemmes efter hvert trin, så du kan lukke og fortsætte senere.","tm.nextBtn":"Næste ▶","tm.go":"Gå","tm.goto":"Gå til linje","tm.back":"◀ Tilbage","tm.board":"Pladen med linjerne, der er viklet indtil nu, og den næste linje fremhævet","tm.after":"Efter","tm.before":"Før","tm.next":"Næste søm","tm.close":"Luk","tm.full":"Fuld skærm","tm.speak":"Sig sømmet højt","tm.title":"Viklevisning","h.presets":"Forvalg","dl.thread":"Viklevisning","in.project":"Åbn et projekt","in.projNote":"Et projekt gemmer billedet, som beregningen så det, ikke det originale foto. Upload fotoet igen for at ændre beskæringen, justeringerne eller penselstrøgene.","h.template":"Sømskabelon","tpl.hint":"Sømmenes placering i fuld størrelse, nummereret, til at tape på pladen. Udskriv i faktisk størrelse (100 %, ikke “tilpas til side”), og kontrollér kvadratet på 100 mm med en lineal.","tpl.paper":"Papir","tpl.pages":"Sider til udskrift","tpl.svg":"Ét ark (SVG)","dl.png":"Forhåndsvisning (PNG)","dl.project":"Projektfil","dl.instructions":"Hent viklevejledningen","dl.csv":"Rækkefølge (CSV)","brush.hint":"Mal på visningen Mål. Varme områder tæller op til tre gange så meget og får flere linjer; kolde områder tæller ned til en femtedel. Brug den til øjne, en mund eller en kant, der betyder noget.","brush.clear":"Fjern penselstrøgene","brush.size":"Penselstørrelse","brush.down":"Mindre vigtigt","brush.up":"Vigtigere","brush.off":"Fra","h.brush":"Vigtighedspensel","h.seen":"Som beregningen ser det","adj.reset":"Nulstil justeringerne","adj.clip":"Klipgrænse (højere forstærker mere)","adj.clahe":"Lokal kontrastforstærkning (CLAHE)","adj.gamma":"Gamma (over 1 gør mellemtonerne mørkere)","adj.contrast":"Kontrast","adj.brightness":"Lysstyrke","h.adjust":"Justér","crop.reset":"Nulstil beskæringen","crop.rotate":"Drej","crop.zoom":"Zoom","crop.hint":"Træk for at flytte billedet; rul eller knib for at zoome.","crop.label":"Billedet under pladens cirkel: træk for at flytte det, rul eller knib for at zoome",title:"String Art — Én tråd, ét billede",meta:"Gør et billede til trådkunst: én sammenhængende tråd viklet mellem søm på en rund ramme. Appen finder den rækkefølge af søm, der bedst gengiver billedet, og viser en realistisk forhåndsvisning — alt sammen i din browser.",sub:"én tråd, ét billede","nav.about":"Om","nav.projects":"← Alle projekter","h.picture":"Billede","in.upload":"Upload et billede","in.sample":"Brug eksemplet","in.thumb":"Billedet, som beregningen ser det","in.hint":"Vælg et billede: et ansigt eller en genstand med stærk kontrast mod en ensfarvet baggrund virker bedst. Intet bliver uploadet; alt kører i din browser.","h.params":"Parametre","run.run":"Beregn","run.pause":"Pause","run.cancel":"Annullér","view.label":"Vis","view.thread":"Tråd","view.target":"Mål","view.both":"Side om side","view.threadLabel":"Forhåndsvisning af tråden på pladen","view.threadCap":"tråd, tegnet i sin rigtige tykkelse","view.targetLabel":"Målet, beregningen sigter efter","view.targetCap":"ønsket mørke","h.metrics":"Resultat","log.summary":"Beregningslog","about.title":"Om String Art","about.back":"← Tilbage til appen","about.h1":"Om String Art","about.p1":"String Art gør et billede til en vejledning til et klassisk stykke håndværk: søm rundt om en rund plade og én sort tråd, viklet fra søm til søm tusindvis af gange, indtil trådens krydsninger tegner billedet. Appen regner rækkefølgen af søm ud og viser, hvordan det færdige værk kommer til at se ud.","about.h.how":"Sådan vælger den linjerne","about.how":"Billedet bliver til et kort over, hvor mørkt hvert punkt skal være. Fra ét søm prøver appen hver linje, den må vikle som den næste, og beholder den, der bringer den simulerede plade tættest på kortet; derefter fortsætter den fra linjens ende. Tråden gør pladen mørk, som rigtig tråd gør: hver gang dækker den en del af det hvide, der stadig ses, så krydsninger bliver mørkere, men aldrig mørkere end sort. Den stopper, når den når det højeste antal linjer, du tillader, eller når ingen linje gør billedet bedre længere.","about.h.numbers":"Tallene","about.numbers":"RMSE måler, hvor langt den simulerede plade er fra målet, pixel for pixel (0 er et perfekt match). SSIM sammenligner lokal lysstyrke, kontrast og struktur (1 er ens); fordi tråd er en fin tekstur af linjer, giver appen også SSIM efter en let sløring, tættere på det, du ser fra et par skridts afstand. Trådlængden er summen af alle linjerne plus 10 % til omvikling om sømmene og slæk.","about.h.private":"Dine billeder bliver hos dig","about.private":"Alt kører i din browser. Billeder bliver aldrig uploadet.","about.h.status":"Hvad den gør","about.status":"Version 1.0. Forbered billedet — beskær, zoom og drej det, justér lysstyrke, kontrast og gamma, forstærk den lokale kontrast, og mal det, der betyder noget — med et tjek, der advarer om billeder, som ikke vil fungere godt; vælg et forvalg eller indstil hver parameter; og se tråden blive viklet på. Udskriv derefter sømskabelonen i fuld størrelse og viklevejledningen, og vikl værket med viklevisningen, der viser (og kan sige) det næste søm og husker, hvor du er. Dine indstillinger og dit seneste resultat huskes i denne browser."}},u="sa-lang",d={en:{name:"English",html:"en",locale:"en-US",label:"Language"},es:{name:"Español",html:"es-419",locale:"en-US",label:"Idioma"},da:{name:"Dansk",html:"da",locale:"da-DK",label:"Sprog"}},g={en:null,es:c,da:p},m=e=>e==="en"||e==="es"||e==="da";function b(){if(typeof location>"u")return"en";let e=null;try{e=new URLSearchParams(location.search).get("lang")}catch{e=null}if(m(e)){try{localStorage.setItem(u,e)}catch{}return e}try{const r=localStorage.getItem(u);if(m(r))return r}catch{}const a=typeof navigator<"u"&&(navigator.languages?.[0]||navigator.language)||"";return/^es\b/i.test(a)?"es":/^da\b/i.test(a)?"da":"en"}const o=b(),l=g[o],h=d[o].locale,v=(e,a)=>a?e.replace(/\{(\w+)\}/g,(r,i)=>a[i]!=null?String(a[i]):r):e;function k(e,a){const r=l?.T[e];return v(r??e,a)}function j(e,a){const r=e.toFixed(a);return o==="da"?r.replace(".",","):r}function y(e){return Math.round(e).toLocaleString(h)}function f(e){return o==="en"?e:e.replace(/^([^#?]*)(\?[^#]*)?/,(a,r,i)=>{const n=new URLSearchParams((i||"").slice(1));return n.set("lang",o),r+"?"+n.toString()})}function S(e=document){if(document.documentElement.lang=d[o].html,l){e.querySelectorAll("[data-i18n]").forEach(r=>{const i=l.H[r.dataset.i18n];i!=null&&(r.innerHTML=i)}),e.querySelectorAll("[data-i18n-attr]").forEach(r=>{r.dataset.i18nAttr.split(",").forEach(i=>{const[n,t]=i.split("="),s=l.H[t];s!=null&&r.setAttribute(n,s)})});const a=document.querySelector("title[data-i18n]");a&&l.H[a.dataset.i18n]&&(document.title=l.H[a.dataset.i18n])}e.querySelectorAll("a[href]").forEach(a=>{const r=a.getAttribute("href");/^(index|about)\.html/.test(r)&&a.setAttribute("href",f(r))})}function w(){const e=document.getElementById("langSel");e&&(e.innerHTML=Object.keys(d).map(a=>`<option value="${a}" lang="${d[a].html}">${d[a].name}</option>`).join(""),e.value=o,e.setAttribute("aria-label",d[o].label),e.addEventListener("change",()=>{const a=e.value;if(a===o)return;try{localStorage.setItem(u,a)}catch{}const r=new URLSearchParams(location.search);r.set("lang",a),location.href=location.pathname+"?"+r.toString()+location.hash}))}const q="1.0.0";export{d as L,k as T,q as V,S as a,h as b,j as f,y as i,o as l,w as m};
